            const omitFlat=(first+i===1 && ev.step==='E' && ev.alt===-1) ||
                (first+i===4 && j===3 && ev.step==='B' && ev.alt===-1) ||
                (first+i===5 && j===5 && ev.step==='B' && ev.alt===-1);
            const token=(triplet?'(3':'')+fgAbcNote(ev,omitFlat)+duration+(tied?'-':'');
